function layout({ title, body, canonical = '' }) {
  const canonicalTag = canonical ? `<link rel="canonical" href="${escapeHtml(canonical)}">` : '';
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  ${canonicalTag}
  <style>${css}</style>
</head>
<body>
  <div class="wrap">
    <header>
      <a class="brand" href="/">Reading list</a>
      <a class="button" href="/books/new">Add a book</a>
    </header>
    <main>
      ${body}
    </main>
  </div>
</body>
</html>`;
}

function bookItem(book, { canFinish }) {
  const href = bookPath(book.id);
  const title = book.title || 'Untitled';
  const finishForm = canFinish
    ? `<form method="post" action="${escapeHtml(href)}/finish">
        <input type="hidden" name="next" value="/">
        <button class="secondary" type="submit" aria-label="Mark ${escapeHtml(title)} finished">Mark finished</button>
      </form>`
    : '';
  return `<li class="book${canFinish ? '' : ' done'}">
    <a href="${escapeHtml(href)}">
      <span class="title">${escapeHtml(title)}</span>
      <span class="author">${escapeHtml(book.author || 'Unknown author')}</span>
    </a>
    ${finishForm}
  </li>`;
}

function bookSection({ id, heading, books, empty, canFinish }) {
  const count = `<span class="count">${books.length}</span>`;
  const content = books.length
    ? `<ul class="list">${books.map((book) => bookItem(book, { canFinish })).join('')}</ul>`
    : `<p class="empty">${empty}</p>`;
  return `<section aria-labelledby="${id}">
    <h2 id="${id}">${heading} ${count}</h2>
    ${content}
  </section>`;
}

export function homePage({ reading, finished }) {
  const body = [
    bookSection({
      id: 'reading-heading',
      heading: 'Currently reading',
      books: reading,
      canFinish: true,
      empty: 'Nothing in progress. <a href="/books/new">Add a book</a>.',
    }),
    bookSection({
      id: 'finished-heading',
      heading: 'Finished',
      books: finished,
      canFinish: false,
      empty: 'No finished books yet.',
    }),
  ].join('');
  return layout({ title: 'Reading list', body });
}

export function newBookPage({ values, errors }) {
  const errorBlock = errors.length
    ? `<div class="errors" role="alert">${errors.map((error) => `<p>${escapeHtml(error)}</p>`).join('')}</div>`
    : '';
  const body = `<h1>Add a book</h1>
    ${errorBlock}
    <form method="post" action="/books">
      <label for="title">Title</label>
      <input id="title" name="title" required maxlength="200" value="${escapeHtml(values.title || '')}">
      <label for="author">Author</label>
      <input id="author" name="author" required maxlength="200" value="${escapeHtml(values.author || '')}">
      <label for="notes">Notes</label>
      <textarea id="notes" name="notes" maxlength="5000">${escapeHtml(values.notes || '')}</textarea>
      <div class="actions"><button type="submit">Add book</button></div>
    </form>`;
  return layout({ title: 'Add a book · Reading list', body });
}

export function bookPage({ book, shareUrl }) {
  const finished = book.status === 'finished';
  const notes = book.notes ? escapeHtml(book.notes) : '<span class="muted">No notes yet.</span>';
  const finishForm = finished
    ? ''
    : `<form method="post" action="${escapeHtml(bookPath(book.id))}/finish">
        <input type="hidden" name="next" value="${escapeHtml(bookPath(book.id))}">
        <button type="submit">Mark finished</button>
      </form>`;
  const body = `<p class="status${finished ? ' done' : ''}">${finished ? 'Finished' : 'Currently reading'}</p>
    <h1>${escapeHtml(book.title || 'Untitled')}</h1>
    <p class="author">${escapeHtml(book.author || 'Unknown author')}</p>
    <h2>Notes</h2>
    <div class="notes">${notes}</div>
    <div class="actions">${finishForm}</div>
    <section class="share">
      <h2>Link to this book</h2>
      <p class="muted">Send this address to open just this book.</p>
      <input id="share-link" readonly value="${escapeHtml(shareUrl)}" aria-label="Link to this book">
    </section>`;
  return layout({
    title: `${book.title || 'Book'} · Reading list`,
    canonical: shareUrl,
    body,
  });
}

export function notFoundPage(message = "That page isn't here.") {
  const body = `<h1>Not found</h1><p>${escapeHtml(message)}</p>`;
  return layout({ title: 'Not found · Reading list', body });
}
"}

{"path":"/workspace/src/app.js","content":"import { bookPath, safeNext, splitBooks, validateBookInput } from './books.js';
import { bookPage, homePage, newBookPage, notFoundPage } from './html.js';
import { createStore } from './store.js';

const BODY_LIMIT = 64 * 1024;

function sendHtml(res, status, body) {
  res.writeHead(status, {
    'content-type': 'text/html; charset=utf-8',
    'cache-control': 'no-store',
    'x-content-type-options': 'nosniff',
  });
  res.end(body);
}

function sendText(res, status, message, headers = {}) {
  res.writeHead(status, {
    'content-type': 'text/plain; charset=utf-8',
    'cache-control': 'no-store',
    ...headers,
  });
  res.end(message);
}

function redirect(res, location) {
  res.writeHead(303, {
    location,
    'content-type': 'text/plain; charset=utf-8',
    'cache-control': 'no-store',
  });
  res.end('See other');
}

function normalizePath(pathname) {
  if (pathname.length > 1 && pathname.endsWith('/')) return pathname.slice(0, -1);
  return pathname;
}

function readBody(req) {
  const declared = Number(req.headers['content-length'] || 0);
  if (Number.isFinite(declared) && declared > BODY_LIMIT) {
    const error = new Error('That form is too large.');
    error.statusCode = 413;
    return Promise.reject(error);
  }

  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    let settled = false;
    const finish = (fn, value) => {
      if (settled) return;
      settled = true;
      fn(value);
    };

    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > BODY_LIMIT) {
        const error = new Error('That form is too large.');
        error.statusCode = 413;
        finish(reject, error);
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => finish(resolve, Buffer.concat(chunks).toString('utf8')));
    req.on('error', (error) => finish(reject, error));
  });
}

function parsePayload(raw, contentType) {
  const type = String(contentType || '').toLowerCase();
  if (type.includes('application/json')) {
    try {
      const value = JSON.parse(raw || '{}');
      if (!value || typeof value !== 'object' || Array.isArray(value)) {
        throw new Error('Expected an object');
      }
      return value;
    } catch {
      const error = new Error('Could not read that request.');
      error.statusCode = 400;
      throw error;
    }
  }
  if (type && !type.includes('application/x-www-form-urlencoded') && !type.includes('text/plain')) {
    const error = new Error('Use the book form to add a book.');
    error.statusCode = 415;
    throw error;
  }
  return Object.fromEntries(new URLSearchParams(raw));
}

function requestOrigin(req) {
  const forwarded = String(req.headers['x-forwarded-proto'] || '')
    .split(',')[0]
    .trim()
    .toLowerCase();
  const proto = forwarded === 'https' ? 'https' : 'http';
  const host = String(req.headers.host || 'localhost');
  if (!/^[A-Za-z0-9.:\-[\]]+$/.test(host)) return 'http://localhost';
  return `${proto}://${host}`;
}

export function createApp({ dataFile }) {
  const store = createStore(dataFile);

  async function handle(req, res) {
    const url = new URL(req.url || '/', 'http://localhost');
    const pathname = normalizePath(url.pathname);
    const method = req.method || 'GET';

    if (method === 'GET' && pathname === '/favicon.ico') {
      res.writeHead(204);
      res.end();
      return;
    }

    if (pathname === '/books' && method === 'GET') {
      redirect(res, '/');
      return;
    }

    if (pathname === '/' && method === 'GET') {
      const groups = splitBooks(await store.list());
      sendHtml(res, 200, homePage(groups));
      return;
    }

    if (pathname === '/books/new' && method === 'GET') {
      sendHtml(res, 200, newBookPage({ values: { title: '', author: '', notes: '' }, errors: [] }));
      return;
    }

    if (pathname === '/books' && method === 'POST') {
      const payload = parsePayload(await readBody(req), req.headers['content-type']);
      const input = validateBookInput(payload);
      if (input.errors.length) {
        sendHtml(res, 400, newBookPage({ values: input, errors: input.errors }));
        return;
      }
      const book = await store.add(input);
      redirect(res, bookPath(book.id));
      return;
    }

    const finishMatch = pathname.match(/^\/books\/([^/]+)\/finish$/);
    if (finishMatch) {
      if (method !== 'POST') {
        sendText(res, 405, 'Use the finish button to mark a book finished.', { allow: 'POST' });
        return;
      }
      const id = decodeURIComponent(finishMatch[1]);
      const raw = await readBody(req);
      const payload = raw ? parsePayload(raw, req.headers['content-type']) : {};
      const book = await store.finish(id);
      if (!book) {
        sendHtml(res, 404, notFoundPage("That book isn't on the shelf."));
        return;
      }
      redirect(res, safeNext(payload.next, bookPath(book.id)));
      return;
    }

    const bookMatch = pathname.match(/^\/books\/([^/]+)$/);
    if (bookMatch) {
      if (method !== 'GET') {
        sendText(res, 405, 'Open the book page in the browser.', { allow: 'GET' });
        return;
      }
      const book = await store.get(decodeURIComponent(bookMatch[1]));
      if (!book) {
        sendHtml(res, 404, notFoundPage("That book isn't on the shelf."));
        return;
      }
      const shareUrl = `${requestOrigin(req)}${bookPath(book.id)}`;
      sendHtml(res, 200, bookPage({ book, shareUrl }));
      return;
    }

    if (method !== 'GET' && method !== 'HEAD') {
      sendText(res, 405, 'That action is not available.', { allow: 'GET' });
      return;
    }
    sendHtml(res, 404, notFoundPage());
  }

  return { handle, store };
}
"}

{"path":"/workspace/src/server.js","content":"import http from 'node:http';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { createApp } from './app.js';
import { createStore } from './store.js';

export function defaultDataFile() {
  if (process.env.BOOKS_FILE) return path.resolve(process.env.BOOKS_FILE);
  return path.join(process.cwd(), 'data', 'books.json');
}

export function createServer({ dataFile = defaultDataFile() } = {}) {
  const app = createApp({ dataFile });
  return http.createServer((req, res) => {
    Promise.resolve(app.handle(req, res)).catch((error) => {
      console.error(error);
      if (res.headersSent || res.writableEnded) return;
      const status = Number(error.statusCode);
      if (status >= 400 && status < 500) {
        res.writeHead(status, { 'content-type': 'text/plain; charset=utf-8' });
        res.end(error.message);
        return;
      }
      res.writeHead(500, { 'content-type': 'text/plain; charset=utf-8' });
      res.end('Something went wrong with the reading list.');
    });
  });
}

export function startServer({ dataFile = defaultDataFile(), port = 3000, host = '127.0.0.1' } = {}) {
  const server = createServer({ dataFile });
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, host, () => {
      server.off('error', reject);
      resolve(server);
    });
  });
}

async function main() {
  const dataFile = defaultDataFile();
  const port = Number(process.env.PORT || 3000);
  const host = process.env.HOST || '127.0.0.1';
  if (!Number.isInteger(port) || port <= 0 || port > 65535) {
    console.error(`Invalid PORT: ${process.env.PORT}`);
    process.exit(1);
  }

  try {
    await createStore(dataFile).init();
    const server = await startServer({ dataFile, port, host });
    const address = server.address();
    const shownPort = address && typeof address === 'object' ? address.port : port;
    console.log(`Reading list at http://${host}:${shownPort}`);
    console.log(`Saving books to ${dataFile}`);
  } catch (error) {
    console.error(error.message);
    process.exit(1);
  }
}

const invokedDirectly =
  process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href;

if (invokedDirectly) {
  await main();
}
"}

{"path":"/workspace/test/app.test.js","content":"import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { startServer } from '../src/server.js';

let ctx;

async function start(file) {
  const server = await startServer({ dataFile: file, port: 0, host: '127.0.0.1' });
  const address = server.address();
  return { server, base: `http://127.0.0.1:${address.port}` };
}

async function close(server) {
  if (!server) return;
  await new Promise((resolve, reject) => server.close((error) => (error ? reject(error) : resolve())));
}

function section(html, heading) {
  const marker = `<h2 id="${heading === 'Finished' ? 'finished-heading' : 'reading-heading'}">${heading}`;
  const start = html.indexOf(marker);
  expect(start).toBeGreaterThan(-1);
  const rest = html.slice(start);
  const next = rest.indexOf('<h2 ', marker.length);
  return next === -1 ? rest : rest.slice(0, next);
}

beforeEach(async () => {
  const dir = await mkdtemp(path.join(tmpdir(), 'reading-list-'));
  const file = path.join(dir, 'books.json');
  const started = await start(file);
  ctx = { dir, file, ...started };
});

afterEach(async () => {
  await close(ctx?.server);
  if (ctx?.dir) await rm(ctx.dir, { recursive: true, force: true });
});

async function postForm(pathname, fields) {
  return fetch(`${ctx.base}${pathname}`, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });
}

describe('reading list', () => {
  it('shows currently reading and finished books', async () => {
    const response = await fetch(`${ctx.base}/`);
    expect(response.status).toBe(200);
    const html = await response.text();
    expect(section(html, 'Currently reading')).toContain('Nothing in progress');
    expect(section(html, 'Finished')).toContain('No finished books yet');
  });

  it('adds a book from the form and opens its page', async () => {
    const form = await fetch(`${ctx.base}/books/new`);
    expect(await form.text()).toContain('name="notes"');

    const created = await postForm('/books', {
      title: 'The Dispossessed',
      author: 'Ursula K. Le Guin',
      notes: 'Anarres first.',
    });
    expect(created.status).toBe(303);
    const location = created.headers.get('location');
    expect(location).toMatch(/^\/books\/[^/]+$/);

    const home = await (await fetch(`${ctx.base}/`)).text();
    expect(section(home, 'Currently reading')).toContain('The Dispossessed');
    expect(section(home, 'Finished')).not.toContain('The Dispossessed');

    const detail = await fetch(`${ctx.base}${location}`);
    expect(detail.status).toBe(200);
    expect(detail.headers.get('set-cookie')).toBeNull();
    const page = await detail.text();
    expect(page).toContain('The Dispossessed');
    expect(page).toContain('Ursula K. Le Guin');
    expect(page).toContain('Anarres first.');
    expect(page).toContain(`${ctx.base}${location}`);
    expect(page).toContain(`rel="canonical" href="${ctx.base}${location}"`);
  });

  it('marks a book finished and keeps it in the JSON file after restart', async () => {
    const created = await postForm('/books', {
      title: 'Kindred',
      author: 'Octavia E. Butler',
      notes: 'Dana and Rufus.',
    });
    const location = created.headers.get('location');
    const finished = await postForm(`${location}/finish`, { next: '/' });
    expect(finished.status).toBe(303);
    expect(finished.headers.get('location')).toBe('/');

