    expect(saved).toEqual([
      expect.objectContaining({
        title: 'Kindred',
        author: 'Octavia E. Butler',
        notes: 'Dana and Rufus.',
        status: 'finished',
        finishedAt: expect.any(String),
      }),
    ]);

    await close(ctx.server);
    ctx.server = null;
    const restarted = await start(ctx.file);
    const again = await (await fetch(`${restarted.base}/`)).text();
    expect(section(again, 'Finished')).toContain('Kindred');
    const shared = await fetch(`${restarted.base}${location}`);
    expect(shared.status).toBe(200);
    expect(await shared.text()).toContain('Finished');
    await close(restarted.server);
