  it('does not save an incomplete book', async () => {
    const response = await postForm('/books', { title: '   ', author: '', notes: 'lost' });
    expect(response.status).toBe(400);
    const html = await response.text();
    expect(html).toContain('Title is required.');
    expect(html).toContain('Author is required.');
    expect(html).toContain('lost');
    await expect(readFile(ctx.file, 'utf8')).rejects.toThrow();
  });

  it('escapes book text on the page', async () => {
    const created = await postForm('/books', {
      title: '<script>alert(1)</script>',
      author: '"><img src=x onerror=alert(1)>',
      notes: 'a <b>note</b>',
    });
    const page = await (await fetch(`${ctx.base}${created.headers.get('location')}`)).text();
    expect(page).not.toContain('<script>');
    expect(page).not.toContain('<img');
    expect(page).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
    expect(page).toContain('&lt;b&gt;note&lt;/b&gt;');

    const saved = JSON.parse(await readFile(ctx.file, 'utf8'));
    expect(saved[0].title).toBe('<script>alert(1)</script>');
  });

  it('returns not found for an unknown book and ignores a finish visit', async () => {
    expect((await fetch(`${ctx.base}/books/missing`)).status).toBe(404);
    const created = await postForm('/books', {
      title: 'Parable of the Sower',
      author: 'Octavia E. Butler',
      notes: '',
    });
    const visit = await fetch(`${ctx.base}${created.headers.get('location')}/finish`);
    expect(visit.status).toBe(405);
    const saved = JSON.parse(await readFile(ctx.file, 'utf8'));
    expect(saved[0].status).toBe('reading');
  });

  it('does not overwrite a broken books file', async () => {
    await close(ctx.server);
    await writeFile(ctx.file, '{', 'utf8');
    ctx.server = (await start(ctx.file)).server;
    const response = await fetch(`${ctx.base}/`);
    expect(response.status).toBe(500);
    expect(await readFile(ctx.file, 'utf8')).toBe('{');
  });
});
