const LIMITS = {
  title: 200,
  author: 200,
  notes: 5000,
};

export function bookPath(id) {
  return `/books/${encodeURIComponent(id)}`;
}

export function validateBookInput(input) {
  const source = input && typeof input === 'object' ? input : {};
  const title = String(source.title ?? '').trim();
  const author = String(source.author ?? '').trim();
  const notes = String(source.notes ?? '').trim();
  const errors = [];

  if (!title) errors.push('Title is required.');
  else if (title.length > LIMITS.title) errors.push(`Title must be ${LIMITS.title} characters or fewer.`);

  if (!author) errors.push('Author is required.');
  else if (author.length > LIMITS.author) errors.push(`Author must be ${LIMITS.author} characters or fewer.`);

  if (notes.length > LIMITS.notes) errors.push(`Notes must be ${LIMITS.notes} characters or fewer.`);

  return { title, author, notes, errors };
}

export function splitBooks(books) {
  const list = Array.isArray(books) ? books.filter((book) => book && typeof book.id === 'string' && book.id) : [];
  const byNewest = (left, right, field) => String(right[field] || '').localeCompare(String(left[field] || ''));
  const reading = list
    .filter((book) => book.status !== 'finished')
    .sort((left, right) => byNewest(left, right, 'addedAt'));
  const finished = list
    .filter((book) => book.status === 'finished')
    .sort((left, right) => byNewest(left, right, 'finishedAt') || byNewest(left, right, 'addedAt'));
  return { reading, finished };
}

export function safeNext(value, fallback) {
  if (typeof value !== 'string' || value.length > 200) return fallback;
  if (!value.startsWith('/') || value.startsWith('//') || value.includes('\\') || /[\r\n]/.test(value)) {
    return fallback;
  }
  return value;
}

import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';

export function createStore(filePath) {
  let queue = Promise.resolve();
  let tempSeq = 0;

  function run(task) {
    const result = queue.then(task, task);
    queue = result.then(
      () => {},
      () => {},
    );
    return result;
  }

  async function readBooks() {
    let raw;
    try {
      raw = await readFile(filePath, 'utf8');
    } catch (error) {
      if (error && error.code === 'ENOENT') return [];
      throw error;
    }
    if (!raw.trim()) return [];

    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (error) {
      throw new Error(`Could not parse ${filePath}: ${error.message}`);
    }
    if (!Array.isArray(parsed)) {
      throw new Error(`Expected a JSON array in ${filePath}`);
    }
    return parsed;
  }

  async function writeBooks(books) {
    await mkdir(path.dirname(filePath), { recursive: true });
    const tempPath = `${filePath}.${process.pid}.${tempSeq++}.tmp`;
    try {
      await writeFile(tempPath, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
      await rename(tempPath, filePath);
    } catch (error) {
      await rm(tempPath, { force: true });
      throw error;
    }
  }

  return {
    filePath,

    init() {
      return run(async () => {
        try {
          await readFile(filePath, 'utf8');
        } catch (error) {
          if (error && error.code === 'ENOENT') {
            await writeBooks([]);
            return [];
          }
          throw error;
        }
        return readBooks();
      });
    },

    list() {
      return run(() => readBooks());
    },

    get(id) {
      return run(async () => {
        const books = await readBooks();
        return books.find((book) => book && book.id === id) || null;
      });
    },

    add({ title, author, notes }) {
      return run(async () => {
        const books = await readBooks();
        const book = {
          id: randomUUID(),
          title,
          author,
          notes: notes || '',
          status: 'reading',
          addedAt: new Date().toISOString(),
          finishedAt: null,
        };
        books.push(book);
        await writeBooks(books);
        return book;
      });
    },

    finish(id) {
      return run(async () => {
        const books = await readBooks();
        const book = books.find((item) => item && item.id === id);
        if (!book) return null;
        if (book.status !== 'finished') {
          book.status = 'finished';
          book.finishedAt = new Date().toISOString();
          await writeBooks(books);
        }
        return book;
      });
    },
  };
}

import http from 'node:http';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { createApp } from './app.js';
import { createStore } from './store.js';

export function defaultDataFile() {
  if (process.env.BOOKS_FILE) return path.resolve(process.env.BOOKS_FILE);
  return path.join(process.cwd(), 'data', 'books.json');
}

export function createServer({ dataFile = defaultDataFile() } = {}) {
  const app = createApp({ dataFile });
  return http.createServer((req, res) => {
    Promise.resolve(app.handle(req, res)).catch((error) => {
      console.error(error);
      if (res.headersSent || res.writableEnded) return;
      const status = Number(error.statusCode);
      if (status >= 400 && status < 500) {
        res.writeHead(status, { 'content-type': 'text/plain; charset=utf-8' });
        res.end(error.message);
        return;
      }
      res.writeHead(500, { 'content-type': 'text/plain; charset=utf-8' });
      res.end('Something went wrong with the reading list.');
    });
  });
}

export function startServer({ dataFile = defaultDataFile(), port = 3000, host = '127.0.0.1' } = {}) {
  const server = createServer({ dataFile });
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, host, () => {
      server.off('error', reject);
      resolve(server);
    });
  });
}

async function main() {
  const dataFile = defaultDataFile();
  const port = Number(process.env.PORT || 3000);
  const host = process.env.HOST || '127.0.0.1';
  if (!Number.isInteger(port) || port <= 0 || port > 65535) {
    console.error(`Invalid PORT: ${process.env.PORT}`);
    process.exit(1);
  }

  try {
    await createStore(dataFile).init();
    const server = await startServer({ dataFile, port, host });
    const address = server.address();
    const shownPort = address && typeof address === 'object' ? address.port : port;
    console.log(`Reading list at http://${host}:${shownPort}`);
    console.log(`Saving books to ${dataFile}`);
  } catch (error) {
    console.error(error.message);
    process.exit(1);
  }
}

const invokedDirectly =
  process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href;

if (invokedDirectly) {
  await main();
}

